import {qualityReport,issuesCSV} from './quality.js';
import {CITIES,escapeHTML as e,parseRequest,buildGroups,parseCSV,csvRows,toCSV,makeSample,safeURL} from './core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let mode='catalog',tab='records',language='en',raw=[],decisions={},model={groups:[],pairs:[],pending:[]},lastQuery='',plan=null,sourceLog=[],uploads=[],abort=null,aiAvailable=false,lastMode='sample',drawerReturn=null;const STORE='eklist.saved.v1';
const hi={studio:'डेटा स्टूडियो',saved:'सहेजे गए डेटासेट',sources:'स्रोत',method:'यह कैसे काम करता है',headline:'कम उलझन।<br><span>ज़्यादा स्पष्टता।</span>',intro:'बिखरी जानकारी से एक भरोसेमंद सूची बनाएं।<br>पूछें। प्रमाण देखें। अपना डेटा पाएं।',question:'आप कौन सी जानकारी एक साथ लाना चाहते हैं?',build:'डेटासेट बनाएं',sample:'नमूना',live:'लाइव स्रोत',upload:'आपकी CSV',try:'यह पूछें',save:'सहेजें',export:'CSV डाउनलोड',records:'अलग रिकॉर्ड',merged:'डुप्लिकेट जोड़े',review:'समीक्षा ज़रूरी',provenance:'स्रोत उपलब्ध',table:'रिकॉर्ड',reviewtab:'समीक्षा'};const original=new Map($$('[data-i]').map(el=>[el,el.innerHTML]));
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.add('hidden'),3500);}
function notice(msg){$('#notice').textContent=msg;$('#notice').classList.toggle('hidden',!msg);}
function getSaved(){try{return JSON.parse(localStorage.getItem(STORE)||'[]')}catch{return []}}
function savedCount(){$('#saved-count').textContent=getSaved().length;}
function setMode(next){mode=next;if(['sample','live'].includes(mode)&&/college|कॉलेज|universit/i.test($('#query').value))$('#query').value='Find schools in Delhi';$('#search-fallback').classList.toggle('hidden',mode!=='catalog');$$('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));$('#mode-note').textContent=mode==='catalog'?'74,847 source rows · local SQLite · exact AISHE linkage':mode==='sample'?'Illustrative records · no real school or hospital data':mode==='live'?'OpenStreetMap + Wikidata · public data · up to 2,500 records per search':`${uploads.length} CSV file${uploads.length===1?'':'s'} selected · stays in your browser`;}
function refresh(){model=buildGroups(raw,decisions);render();}
function render(){const {groups,pending}=model;const conflicts=groups.filter(g=>g.conflicts.length),merged=raw.length-groups.length,coverage=groups.length?Math.round(groups.filter(g=>g.records.every(r=>r.source)).length/groups.length*100):0,quality=groups.length?Math.round(qualityReport(groups).complete/groups.length*100):0;$('#stat-records').textContent=groups.length;$('#stat-raw').textContent=`From ${raw.length} input records`;$('#stat-merged').textContent=merged;$('#stat-review').textContent=pending.length+conflicts.length;$('#stat-coverage').textContent=coverage+'%';$('#quality-value').textContent=quality+'%';$('#quality-ring').style.strokeDashoffset=308*(1-quality/100);$('#insight-source').textContent=`${groups.length} / ${groups.length}`;$('#insight-conflicts').textContent=conflicts.length;$('#insight-matches').textContent=pending.length;$('#tab-records').textContent=groups.length;$('#tab-review').textContent=pending.length+conflicts.length;$('#dataset-title').innerHTML=`${e(plan?.city?.name||'Combined')} ${plan?.type==='hospital'?'health facilities':plan?.type==='school'?'school directory':plan?.type==='college'?'college directory':plan?.type==='university'?'university directory':'institution directory'} <span class="sample-badge">${lastMode==='sample'?'SAMPLE':lastMode==='live'?'LIVE SOURCES':lastMode==='catalog'?'LOCAL DATABASE':'IMPORTED'}</span>`;$('#dataset-subtitle').textContent=lastMode==='sample'?'Illustrative records, designed to demonstrate matches, branches and conflicts.':`${new Set(raw.map(r=>r.source)).size} source(s) · ${raw.length} records retrieved · ${new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}`;renderTab();}
function renderTab(){const content=$('#tab-content');$('.table-filter').classList.toggle('hidden',tab!=='records');$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',String(b.dataset.tab===tab));});if(tab==='records'){const q=$('#table-search').value.toLowerCase(),filter=$('#status-filter').value;const list=model.groups.filter(g=>(JSON.stringify(g.values).toLowerCase().includes(q))&&(filter==='all'||filter==='merged'&&g.merged||filter==='conflict'&&g.conflicts.length||filter==='single'&&!g.merged));content.innerHTML=list.length?`<div class="table-scroll"><table><thead><tr><th>#</th><th>ENTITY NAME</th><th>LOCATION</th><th>STATUS</th><th>SOURCES</th><th></th></tr></thead><tbody>${list.slice(0,100).map((g,i)=>`<tr class="record-row" tabindex="0" data-record="${e(g.id)}" aria-label="Inspect ${e(g.name)}"><td class="row-num">${String(i+1).padStart(2,'0')}</td><td><div class="record-name"><span class="record-icon">${plan?.type==='hospital'?'✚':'▥'}</span><div><strong>${e(g.name)}</strong><small>${e(g.values.entityId[0]||'No shared identifier')}</small></div></div></td><td>${e(g.city||'Not provided')}<small>${e(g.address||'Address not provided')}</small></td><td><span class="pill ${g.conflicts.length?'conflict':g.merged?'merged':''}">${g.conflicts.length?'◌ Conflict':g.merged?'✓ Merged':'· Single source'}</span></td><td><span class="source-pill">${new Set(g.records.map(r=>r.source)).size} source${new Set(g.records.map(r=>r.source)).size>1?'s':''}</span></td><td>↗</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><span>⌕</span>No matching records. Try a different search or filter.</div>';$('#table-count').textContent=`Showing ${Math.min(100,list.length)} of ${list.length} matching records · ${model.groups.length} total records`;}
else if(tab==='quality'){const report=qualityReport(model.groups);content.innerHTML=`<article class="source-card"><h4>Field verification worklist</h4><p>${report.complete} / ${report.total} records have address, city, phone and an identifier, with no detected conflicts. Completeness is not verification. Public directories may omit these fields.</p><button class="secondary" id="export-gaps">Export verification worklist ↓</button></article>`+report.issues.slice(0,100).map(i=>`<article class="review-card"><span class="pill conflict">${e(i.code.replaceAll('_',' '))}</span><h4>${e(i.name)}</h4><p>${e(i.detail)}</p><button class="text-button" data-record="${e(i.groupId)}">Inspect source evidence ↗</button></article>`).join('');$('#export-gaps').onclick=()=>download('eklist-field-verification.csv',issuesCSV(report),'text/csv');$('#table-count').textContent=`${report.issues.length} issues to verify · first 100 shown, all in export`;}
else if(tab==='review'){const conflicts=model.groups.filter(g=>g.conflicts.length);content.innerHTML=[...model.pending.map(p=>{const a=raw.find(r=>r.id===p.a),b=raw.find(r=>r.id===p.b);return `<article class="review-card"><span class="pill conflict">Possible match · human review</span><div class="review-pair"><div>${e(a.name)}<small>${e(a.address)} · ${e(a.source)}</small></div><span>⇄</span><div>${e(b.name)}<small>${e(b.address)} · ${e(b.source)}</small></div></div><p>${e(p.reason)}</p><div class="review-actions"><button class="dark-button" data-decision="merge" data-key="${e(p.key)}">Same entity · merge</button><button class="secondary" data-decision="separate" data-key="${e(p.key)}">Keep separate</button></div></article>`}),...conflicts.map(g=>`<article class="review-card"><span class="pill conflict">Field conflict</span><h4 style="margin-top:12px">${e(g.name)}</h4><p>Different values for ${e(g.conflicts.join(', '))}. Both versions are preserved in export; no value has been silently chosen.</p><button class="secondary" data-record="${e(g.id)}">Inspect evidence ↗</button></article>`)].join('')||'<div class="empty"><span>✓</span>No pending matches or conflicting fields.</div>';const decided=model.pairs.filter(p=>p.kind!=='possible');if(decided.length)content.innerHTML+=`<article class="review-card"><h4>Decision ledger · ${decided.length}</h4>${decided.map(p=>`<p>${p.kind==='merge'?'✓ Merged':'↔ Kept separate'} · ${e(raw.find(r=>r.id===p.a)?.name)} / ${e(raw.find(r=>r.id===p.b)?.name)}<br>${e(p.reason||'User decision')} ${p.manual?'<b>Human decision</b>':''} ${p.manual?`<button class="text-button" data-undo="${e(p.key)}">Undo</button>`:''}</p>`).join('')}</article>`;$('#table-count').textContent=`${model.pending.length} possible matches · ${conflicts.length} conflicts`;}
else{const sources=[...new Set(raw.map(r=>r.source))];content.innerHTML=sources.map(s=>{const rs=raw.filter(r=>r.source===s),url=safeURL(rs.find(r=>r.sourceUrl)?.sourceUrl);return `<article class="source-card"><h4>◎ ${e(s)}</h4><p>${rs.length} records · Retrieved ${e(new Date(rs[0].retrieved).toLocaleString())}<br>${lastMode==='sample'?'Synthetic example records; not an official directory.':s==='OpenStreetMap'?'© OpenStreetMap contributors · ODbL. Completeness and currency vary.':s==='Wikidata'?'Wikidata structured data · CC0. Coverage varies by entity and location.':'User-provided data. Confirm permission and attribution before sharing.'}</p>${url?`<a href="${e(url)}" target="_blank" rel="noreferrer">Open source ↗</a>`:''}</article>`;}).join('');content.innerHTML+=sourceLog.map(s=>`<article class="source-card"><h4>${e(s.name)} · ${e(s.status)}</h4><p>${e(s.detail)}</p></article>`).join('');$('#table-count').textContent=`${sources.length} contributing sources`;}}
function openRecord(id){const g=model.groups.find(g=>g.id===id);if(!g)return;drawerReturn=document.activeElement;$('#drawer-content').innerHTML=`<h2>${e(g.name)}</h2><span class="pill ${g.conflicts.length?'conflict':'merged'}">${g.records.length} original record${g.records.length===1?'':'s'} preserved</span><p>${g.merged?'Connected records retain their original field values and sources.':'This record has not been merged with another entity.'}</p>${['name','entityId','state','district','website','management','university','address','phone'].map(f=>`<div class="evidence-field"><label>${f==='entityId'?'Explicit identifier':f}</label>${g.values[f].length?g.values[f].map(value=>`<div class="evidence-value">${f==='website'&&safeURL(value)?`<a href="${e(safeURL(value))}" target="_blank" rel="noreferrer">${e(value)} ↗</a>`:e(value)}${g.records.filter(r=>r[f]===value).map(r=>`<small>${safeURL(r.sourceUrl)?`<a href="${e(r.sourceUrl)}" target="_blank" rel="noreferrer">${e(r.source)} ↗</a>`:e(r.source)} · ${r.sourceRow?'row '+r.sourceRow:e(r.id)}</small>`).join('')}</div>`).join(''):'<p>Not provided by the source.</p>'}${g.conflicts.includes(f)?'<p class="evidence-warning">Conflicting values. Verify with the original source; both are retained.</p>':''}</div>`).join('')}${g.records.some(r=>r.supportingEvidence?.length)?`<h3>Official-site evidence candidates</h3>${[...new Map(g.records.flatMap(r=>r.supportingEvidence||[]).map(s=>[s.sha256,s])).values()].map(s=>`<div class="raw-record"><a href="${e(safeURL(s.contact_url||s.url))}" target="_blank" rel="noreferrer">${e(s.name)} ↗</a><p>Matched through a unique website hostname in this catalogue. Email strings below were extracted from the source; no deliverability is claimed.</p><p>${(s.email_candidates||[]).map(e).join('<br>')||'No email extracted'}</p><small>Retrieved ${e(s.retrieved_at)}</small></div>`).join('')}`:''}<h3>Search context is not a source fact</h3><p>${e(g.records.map(r=>r.searchRegion).filter(Boolean).join(", ")||"Imported / sample records")} · City fields are only filled when a source supplies them.</p><h3>Original records</h3>${g.records.map(r=>`<div class="raw-record"><strong>${e(r.source)}</strong><div>${e(r.name)}<br>${e(r.address)}<br>${e(r.phone||'No phone provided')}<br>Source file: ${e(r.source)} · row ${e(r.sourceRow||'—')}<br>Imported/retrieved: ${e(r.retrieved)}${r.original?`<details><summary>Original source fields</summary><pre style="white-space:pre-wrap;font-size:11px">${e(JSON.stringify(r.original,null,2))}</pre></details>`:''}</div></div>`).join('')}${g.merged?`<button class="secondary" data-unmerge="${e(g.id)}">↶ Keep all these records separate</button>`:''}`;$('#drawer').classList.remove('hidden');$('#drawer-backdrop').classList.remove('hidden');$('#close-drawer').focus();document.body.style.overflow='hidden';}
function closeDrawer(){$('#drawer').classList.add('hidden');$('#drawer-backdrop').classList.add('hidden');document.body.style.overflow='';drawerReturn?.focus();}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function showMethod(){modal('A little order. All the evidence.',`<p>EkList translates a supported Hindi or English request into a directory query, preserves the source records, and builds a reviewable dataset.</p><h3>01 · Bring sources together</h3><p>Institution database mode searches the five imported national directories using validated filters and exact AISHE identifiers. Live map mode queries OpenStreetMap and Wikidata for schools or hospitals in 24 supported city areas. CSV mode accepts your own files. Sample mode uses clearly labeled synthetic records.</p><h3>02 · Match conservatively</h3><p>Matching explicit identifiers can connect records automatically. Similar names, addresses or phone numbers create review suggestions, not automatic proof. Different explicit identifiers block automatic merging.</p><h3>03 · Keep the evidence</h3><p>Every value retains its source. Conflicting addresses and numbers remain visible. You can reverse a merge and export all alternatives.</p><h3>What the scores mean</h3><p>Source coverage means an origin is attached—not that it is verified. The completeness percentage requires a supplied address, city, phone and identifier, without detected field or location conflicts. Missing information stays missing. It is not a truth score.</p><h3>Language & AI</h3><p>${aiAvailable?'The local server has a model configured for natural-language query planning.':'The bilingual local parser is available. Institution database mode can also use the configured NVIDIA planner.'} The matching rules remain inspectable.</p>`);}
function uploadModal(){modal('Bring your own sources',`<p>Combine CSV files without uploading their contents to a server. Use UTF-8 CSVs with a header row. Maximum 500 total rows / 2 MB per file.</p><div class="upload-zone"><strong>Two lists. One place to make sense of them.</strong><p>Required: <code>name</code><br>Helpful: <code>address, city, phone, entity_id, source_url</code></p><button class="primary" id="choose-files">Choose CSV files ↑</button></div><p>Only use <code>entity_id</code> for a shared identity across sources—not each file’s row number. Prefix the identifier namespace, e.g. <code>udise:123456</code>.</p><button class="secondary" id="template-download">↓ Download example CSV</button><div class="upload-files">${uploads.map(f=>`<div>✓ ${e(f.name)} · ${f.records.length} records</div>`).join('')}</div>${uploads.length?'<button class="dark-button" id="use-uploads" style="margin-top:15px">Build from these files ↗</button>':''}`);$('#choose-files').onclick=()=>$('#file-input').click();$('#template-download').onclick=()=>download('eklist-template.csv','name,address,city,phone,entity_id,source_url\nExample School,"12 Main Road",Delhi,,udise:EXAMPLE,\n','text/csv');if($('#use-uploads'))$('#use-uploads').onclick=()=>{$('#modal').close();$('#query').value='Combine my CSVs and find duplicate records';setMode('upload');run();};}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function fetchJSON(url,options={},signal){const timeout=AbortSignal.timeout(65000);const s=signal?AbortSignal.any([signal,timeout]):timeout;const r=await fetch(url,{...options,signal:s});if(!r.ok)throw Error(`Source returned HTTP ${r.status}`);return r.json();}
async function liveSources(p,signal){const c=p.city,t=p.type;const q=`[out:json][timeout:25];nwr["amenity"="${t}"](${c.bbox.join(',')});out center tags 2001;`;const sparql=`SELECT ?item ?itemLabel ?coord ?address WHERE { SERVICE wikibase:around { ?item wdt:P625 ?coord . bd:serviceParam wikibase:center "Point(${c.lon} ${c.lat})"^^geo:wktLiteral; wikibase:radius "20". } ?item wdt:P31/wdt:P279* wd:${t==='school'?'Q3914':'Q16917'} . OPTIONAL {?item wdt:P6375 ?address. FILTER(LANG(?address)="en")} SERVICE wikibase:label {bd:serviceParam wikibase:language "en,hi".} } LIMIT 501`;const results=await Promise.allSettled([fetchJSON('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:q})},signal),fetchJSON('https://query.wikidata.org/sparql?format=json&query='+encodeURIComponent(sparql),{headers:{Accept:'application/sparql-results+json'}},signal)]);if(signal.aborted)throw new DOMException('Cancelled','AbortError');const now=new Date().toISOString(),records=[],logs=[];results.forEach((res,i)=>{const name=i===0?'OpenStreetMap':'Wikidata';if(res.status==='rejected'){logs.push({name,status:'Unavailable',detail:res.reason.message+'. No data was invented or silently substituted.'});return;}if(i===0){const data=res.value;if((data.elements||[]).length>2000)logs.push({name,status:'Source warning',detail:'Result cap reached: only the first 2,000 OSM objects are included. This is not a complete directory.'});if(data.remark)logs.push({name,status:'Source warning',detail:data.remark});for(const n of (data.elements||[]).slice(0,2000)){const tags=n.tags||{};if(!tags.name&&!tags['name:en']&&!tags['name:hi'])continue;records.push({id:`osm:${n.type}/${n.id}`,name:tags['name:en']||tags.name||tags['name:hi'],address:[tags['addr:housenumber'],tags['addr:street'],tags['addr:suburb'],tags['addr:postcode']].filter(Boolean).join(', '),city:tags['addr:city']||'',searchRegion:c.name,aliases:[tags.name,tags['name:en'],tags['name:hi']].filter(Boolean),original:tags,phone:tags.phone||tags['contact:phone']||'',entityId:tags.wikidata||'',category:t,source:name,sourceUrl:`https://www.openstreetmap.org/${n.type}/${n.id}`,retrieved:now,lat:n.lat??n.center?.lat,lon:n.lon??n.center?.lon});}}else{if((res.value.results?.bindings||[]).length>500)logs.push({name,status:'Source warning',detail:'Result cap reached: only the first 500 Wikidata rows are included.'});const seen=new Set();for(const b of (res.value.results?.bindings||[]).slice(0,500)){const id=b.item.value.split('/').pop();if(seen.has(id))continue;seen.add(id);records.push({id:'wd:'+id,name:b.itemLabel.value,address:b.address?.value||'',city:'',searchRegion:c.name,original:b,lat:b.coord?.value?.match(/Point\(([-\d.]+) ([-\d.]+)\)/)?.[2]??null,lon:b.coord?.value?.match(/Point\(([-\d.]+) ([-\d.]+)\)/)?.[1]??null,phone:'',entityId:id,category:t,source:name,sourceUrl:b.item.value.replace('http:','https:'),retrieved:now});}}logs.push({name,status:'Fetched',detail:`${records.filter(r=>r.source===name).length} named records. ${i===0?'Approximate city search window; up to 2,000 objects.':'20 km city-centre radius; up to 500 rows. These areas are approximate, not official district boundaries.'}`});});return {records,logs};}
async function run(){if(mode==='catalog')return runCatalog();if(abort)return;const query=$('#query').value.trim();if(!query){notice('Describe the dataset you want to create.');return;}if(mode==='upload'&&!uploads.length){uploadModal();return;}abort=new AbortController();const signal=abort.signal;$('#build').disabled=true;$('#run-panel').classList.remove('hidden');$('#run-detail').textContent='Interpreting your request…';notice('');try{let p;if(aiAvailable&&mode!=='upload'){try{const res=await fetchJSON('/api/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query})},signal);if(!res.city||!res.type)throw Error(res.error||'Unsupported request');const city=CITIES.find(c=>c.name===res.city);if(!city||!['school','hospital'].includes(res.type))throw Error('Unsupported query plan');p={city,type:res.type,engine:'AI',query};}catch(err){if(signal.aborted)throw err;p=parseRequest(query,mode);notice('AI planning was unavailable. This request was understood by the supported bilingual rules parser.');}}else p=parseRequest(query,mode);let records=[],logs=[];if(mode==='sample'){records=makeSample(p);logs=[{name:'Sample data',status:'Illustrative',detail:'Fictional entity records. Shared IDs demonstrate consolidation; differing phone numbers demonstrate conflicts. Not suitable for real-world decisions.'}];}else if(mode==='upload'){records=uploads.flatMap(f=>f.records);if(p.city)records=records.filter(r=>r.city.toLowerCase().includes(p.city.name.toLowerCase()));if(p.type)records=records.filter(r=>r.category===p.type||!r.category);logs=[{name:'Uploaded files',status:'Local only',detail:'Files were parsed in your browser. No independent verification of their contents has been performed.'}];}else{$('#run-detail').textContent=`Fetching ${p.type}s near ${p.city.name} from OpenStreetMap and Wikidata…`;const res=await liveSources(p,signal);records=res.records;logs=res.logs;if(!records.length)throw Error('No named records were retrieved. Sources may be unavailable or have no matching coverage. Your previous dataset is unchanged. Try another city or import CSVs.');if(logs.some(l=>l.status==='Unavailable'||l.status==='Source warning'))notice('Partial result: one or more source requests failed or returned a warning. Open Sources for the exact status.');}if(signal.aborted)throw new DOMException('Cancelled','AbortError');raw=records;decisions={};plan=p;lastQuery=query;lastMode=mode;sourceLog=logs;tab='records';$('#table-search').value='';$('#status-filter').value='all';refresh();toast(`${model.groups.length} records ready to explore`);}catch(err){if(err.name==='AbortError'||signal.aborted)toast('Request cancelled. Previous dataset preserved.');else notice(err.message);}finally{abort=null;$('#build').disabled=false;$('#run-panel').classList.add('hidden');}}
$('#query-form').onsubmit=ev=>{ev.preventDefault();run();};$('#cancel-run').onclick=()=>abort?.abort();$$('[data-mode]').forEach(b=>b.onclick=()=>{setMode(b.dataset.mode);if(mode==='upload')uploadModal();});$$('[data-query]').forEach(b=>b.onclick=()=>{$('#query').value=b.dataset.query;$('#query').focus();});$('#upload-shortcut').onclick=()=>{setMode('upload');uploadModal();};$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderTab();});$('#table-search').oninput=renderTab;$('#status-filter').onchange=renderTab;$('#open-review').onclick=()=>{tab='review';renderTab();$('.data-panel').scrollIntoView({behavior:'smooth',block:'center'});};$('#export').onclick=()=>{if(!model.groups.length)return toast('Build a dataset first.');download('eklist-'+(plan?.city?.name||'combined').toLowerCase()+'.csv',toCSV(model.groups),'text/csv;charset=utf-8');toast('CSV exported with sources and conflicting values.');};$('#download-report').onclick=()=>download('eklist-reconciliation.json',JSON.stringify({query:lastQuery,mode:lastMode,engine:plan?.engine,created:new Date().toISOString(),sources:sourceLog,quality:qualityReport(model.groups),decisions:model.pairs,records:raw},null,2),'application/json');
$('#tab-content').onclick=ev=>{const b=ev.target.closest('[data-record],[data-decision],[data-undo]');if(!b)return;if(b.dataset.record)openRecord(b.dataset.record);if(b.dataset.decision){decisions[b.dataset.key]=b.dataset.decision;refresh();toast('Decision recorded. You can undo it in the ledger.');}if(b.dataset.undo){delete decisions[b.dataset.undo];refresh();toast('Decision reversed.');}};$('#tab-content').onkeydown=ev=>{if(ev.key==='Enter'&&ev.target.dataset.record)openRecord(ev.target.dataset.record);};$('#drawer-content').onclick=ev=>{const b=ev.target.closest('[data-unmerge]');if(b){const g=model.groups.find(g=>g.id===b.dataset.unmerge);for(let i=0;i<g.records.length;i++)for(let j=i+1;j<g.records.length;j++)decisions[[g.records[i].id,g.records[j].id].sort().join('::')]='separate';closeDrawer();refresh();toast('Original records restored as separate entities.');}};$('#close-drawer').onclick=closeDrawer;$('#drawer-backdrop').onclick=closeDrawer;$('#close-modal').onclick=()=>$('#modal').close();$('#method-link').onclick=showMethod;$('#settings').onclick=()=>modal('Your workspace',`<p>EkList works without an account. Uploaded files are processed in browser memory; only datasets you explicitly save are stored in this browser.</p><p>Live searches send the selected city and facility type to OpenStreetMap and Wikidata. The optional local AI planner sends your request text to the model provider configured by the server operator.</p><p>Engine: <strong>${aiAvailable?'Model-backed planner available':'Constrained bilingual rules parser'}</strong>. NVIDIA handles public query planning; Serper is called only by the institution search button. Private subscribers are processed locally. ML.ai remains stopped at your request.</p><p>Data-source attribution is retained in exports. Review source licenses before redistributing a combined dataset.</p>`);
