let catalogResult=null;
function canonicalWebsite(value){if(!value)return '';return safeURL(/^https?:\/\//i.test(value)?value:'https://'+value)}
async function runCatalog(useAI){
 if(abort)return;const query=$('#query').value.trim();if(!query)return notice('Enter an institution request.');
 abort=new AbortController();$('#build').disabled=true;$('#run-panel').classList.remove('hidden');$('#run-detail').textContent='Planning filters, then querying the local institution index…';notice('');
 try{
  const response=await fetch('/api/query',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,ai:useAI??$('#use-ai').checked}),signal:AbortSignal.any([abort.signal,AbortSignal.timeout(65000)])});const res=await response.json();if(!response.ok)throw Error(res.error);
  catalogResult=res;const sourceMap=Object.fromEntries(res.sources.map(s=>[s.name,s]));
  raw=res.records.map(r=>({id:r.id,name:r.name,entityId:'aishe:'+r.entity_id,city:r.district,state:r.state,district:r.district,website:canonicalWebsite(r.website),management:r.management,university:r.original['university name']||'',address:'',phone:'',category:r.category,source:r.source,sourceUrl:'',sourceRow:r.source_row,retrieved:sourceMap[r.source]?.imported_at||'',original:r.original,supportingEvidence:r.supporting_evidence||[]}));
  decisions={};plan={city:{name:res.plan.district||res.plan.state||'India'},type:res.plan.category,engine:res.engine};lastMode='catalog';lastQuery=query;tab='records';sourceLog=res.sources.map(s=>({name:s.name,status:'Imported source',detail:`${s.rows} records. ${s.export_label}. SHA-256: ${s.sha256}. File provenance, not independent verification.`}));$('#table-search').value='';refresh();
  $('#dataset-subtitle').textContent=`${res.returned_entities} of ${res.total_matches.toLocaleString()} matching identifiers · ${res.query_ms} ms local query · ${res.engine}${res.cached?' (cached plan)':''}`;
  $('#catalog-summary').textContent=`Applied filters: ${JSON.stringify(res.plan)} · Model calls: ${res.model_calls} · Search calls: 0. ${res.ordering}`;
  $('#search-fallback').classList.remove('hidden');if(res.shortfall)notice(`Only ${res.total_matches} supported matches found; ${res.shortfall} fewer than requested. No records invented.`);else if(res.warning)notice(res.warning);
  $('#quality-value').textContent=(model.groups.length?Math.round(model.groups.filter(g=>g.values.website.length&&g.values.entityId.length&&g.values.state.length).length/model.groups.length*100):0)+'%';document.querySelector('.quality-ring div span').textContent='ID + state + website';
 }catch(err){notice(err.message||'Query failed. Previous data preserved.')}finally{abort=null;$('#build').disabled=false;$('#run-panel').classList.add('hidden')}
}
