$('#source-pack-button').onclick=async()=>{const d=await fetch('/api/source-packs').then(r=>r.json());modal('Research source packs',`<p>${e(d.note||'Local source snapshots')}</p>${d.sources.map(s=>`<article class="source-card"><h4>${e(s.name)}</h4><p>${e(s.status)} · ${e(s.period||'Publication date not established')}<br>${e(s.retrieved_at)}<br>${e(s.extraction_status||'Original document retained')}</p><a href="${e(safeURL(s.contact_url||s.url))}" target="_blank" rel="noreferrer">Open official source ↗</a></article>`).join('')}`)};
let subscriberPrivate=false;let subscriberImport=null;const subscriberDecisions={};
async function subscribersView(){
 modal('Subscriber studio',`<p>Fictional demo by default. Exact normalized LinkedIn/X associations propose linked profiles. Country differences do not block linkage; no country correction is performed.</p><div class="integration-bar"><button class="secondary" id="sub-demo">Fictional demo</button><button class="secondary" id="sub-private">Local private file</button><button class="primary" id="sub-upload">Upload subscriber CSV ↑</button><input type="file" id="sub-file" accept=".csv,text/csv" hidden><input id="sub-filter" placeholder="Filter linked groups by name" aria-label="Filter subscriber groups"><button class="secondary" id="sub-find">Find</button></div><div id="sub-result">Loading…</div>`);
 const load=async()=>{const holder=$('#sub-result');holder.textContent='Finding shared profile associations…';try{const response=subscriberImport?null:await fetch('/api/subscribers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({private:subscriberPrivate,filter:$('#sub-filter').value})});const d=subscriberImport||await response.json();if(response&&!response.ok)throw Error(d.error);const allGroups=d.groups;const filter=$('#sub-filter').value.toLowerCase();const visibleGroups=allGroups.filter(g=>!filter||JSON.stringify(g).toLowerCase().includes(filter)).slice(0,100);holder.innerHTML=`<p><strong>${d.synthetic?'SYNTHETIC DEMO':d.imported?'YOUR CSV · LOCAL ONLY':'PRIVATE · LOCAL ONLY'}</strong> · ${d.input_records.toLocaleString()} source rows · ${d.linked_groups} candidate groups · ${d.records_in_groups} linked rows.</p><p>${e(d.note)}</p><p>Showing ${visibleGroups.length} of ${d.matching_groups??allGroups.length} matching groups. Preferred email: unknown without engagement and subscription evidence.</p>${visibleGroups.map(g=>`<article class="review-card"><h4>${e(g.name)} · ${g.records.length} records</h4><p class="pill">${e(subscriberDecisions[(subscriberImport?'import:':subscriberPrivate?'private:':'demo:')+g.id]||'Needs identity review')}</p><div class="review-actions"><button class="secondary" data-sub-decision="Confirmed same person" data-sub-id="${e(g.id)}">Confirm same person</button><button class="secondary" data-sub-decision="Keep separate" data-sub-id="${e(g.id)}">Keep separate</button><button class="text-button" data-sub-decision="" data-sub-id="${e(g.id)}">Undo</button></div><p>${g.emails.map(e).join('<br>')}</p><details><summary>Matching evidence and original records</summary><pre style="white-space:pre-wrap;font-size:11px">${e(JSON.stringify({evidence:g.evidence,records:g.records},null,2))}</pre></details></article>`).join('')}<button class="secondary" id="sub-export">Export profile evidence JSON</button>${d.imported?'<button class="primary" id="sub-list-export">Download subscriber list CSV ↓</button>':''}`;$('#sub-export').onclick=()=>download(d.synthetic?'eklist-fictional-profiles.json':'eklist-private-profiles.json',JSON.stringify({...d,groups:d.groups.map(g=>({...g,review_decision:subscriberDecisions[(subscriberImport?'import:':subscriberPrivate?'private:':'demo:')+g.id]||'unreviewed'}))},null,2),'application/json');if(d.imported)$('#sub-list-export').onclick=()=>exportSubscriberList(d);holder.onclick=ev=>{const b=ev.target.closest('[data-sub-id]');if(b){subscriberDecisions[(subscriberImport?'import:':subscriberPrivate?'private:':'demo:')+b.dataset.subId]=b.dataset.subDecision;load()}}}catch(err){holder.textContent=err.message}};
 $('#sub-demo').onclick=()=>{subscriberPrivate=false;subscriberImport=null;load()};$('#sub-private').onclick=()=>{subscriberPrivate=true;subscriberImport=null;load()};$('#sub-find').onclick=load;$('#sub-upload').onclick=()=>$('#sub-file').click();$('#sub-file').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Use a CSV smaller than 5 MB.');return}const text=await file.text();let parsed;try{parsed=parseCSV(text)}catch(err){toast(err.message);return}const headers=Object.keys(parsed[0]);const fields=['Email','First Name','Last Name','Linkedin','Twitter/X','Company','Role','Country'];const holder=$('#sub-result');holder.innerHTML=`<h3>Map your columns</h3><p>${e(file.name)} · ${parsed.length} rows. Only Email is required. Shared personal LinkedIn/X profiles enable candidate linking. Names alone never merge.</p>${fields.map(f=>`<label style="display:block;margin:8px 0">${e(f)} <select data-map="${e(f)}"><option value="">Not supplied</option>${headers.map(h=>`<option value="${e(h)}" ${h===f.toLowerCase().replaceAll(' ','_').replace('/','')||h===f.toLowerCase()?'selected':''}>${e(h)}</option>`).join('')}</select></label>`).join('')}<button class="primary" id="sub-import-confirm">Create reviewable list ↗</button>`;$('#sub-import-confirm').onclick=async()=>{const mapping=Object.fromEntries([...holder.querySelectorAll('[data-map]')].map(el=>[el.dataset.map,el.value]).filter(x=>x[1]));try{const normalizedCSV=[headers,...parsed.map(r=>headers.map(h=>r[h]))].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const response=await fetch('/api/subscribers/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csv:normalizedCSV,mapping})});const data=await response.json();if(!response.ok)throw Error(data.error);subscriberImport=data;subscriberPrivate=false;for(const key of Object.keys(subscriberDecisions))if(key.startsWith('import:'))delete subscriberDecisions[key];load()}catch(err){toast(err.message)}}};load();
}
$('#subscriber-studio').onclick=()=>{subscriberPrivate=false;subscribersView()};

function exportSubscriberList(data){const used=new Set(),rows=[];for(const g of data.groups){if(subscriberDecisions['import:'+g.id]!=='Confirmed same person')continue;g.records.forEach(r=>used.add(r.row));rows.push([g.id,g.name,g.emails.join(' | '),g.records.map(r=>r.row).join(' | '),'user-confirmed',''])}data.records.forEach((r,i)=>{if(!used.has(i+2))rows.push(['row-'+(i+2),[r['First Name'],r['Last Name']].filter(Boolean).join(' '),r.Email,i+2,'separate / not confirmed',''])});const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'$&").replaceAll('"','""')+'"';download('eklist-subscriber-list.csv','\ufeff'+[['profile_id','name','emails','source_rows','review_status','preferred_email'],...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');toast(rows.length+' rows exported. Unconfirmed candidates remain separate.')}

// Universal, user-mapped tabular imports; no LLM or web transmission.
let universalFile=null,universalPreview=null;
function universalModal(){modal('Bring any tabular list',`<p>Import downloaded CSV/XLSX files, map their columns, and retain source evidence. Up to 5,000 combined records; XLSX uses the first worksheet. The file goes only to this local server for parsing.</p><input type="file" id="universal-file" accept=".csv,.xlsx"><label style="display:block;margin:14px 0">XLSX header row <input type="number" id="universal-header" min="1" max="20" value="1" style="width:65px"> <small>AISHE exports usually use row 3.</small></label><button class="secondary" id="universal-preview">Preview columns</button><div id="universal-mapping"></div>`);$('#universal-file').onchange=ev=>universalFile=ev.target.files[0];$('#universal-preview').onclick=previewUniversal}
async function previewUniversal(){const f=universalFile;if(!f)return toast('Choose a file first.');if(f.size>5*1024*1024)return toast('Maximum file size is 5 MB.');try{const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const res=await fetch('/api/files/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:f.name,base64:btoa(binary),header_index:Number($('#universal-header').value)-1})});const d=await res.json();if(!res.ok)throw Error(d.error);universalPreview=d;const map=$('#universal-mapping');const fields=['name','entity_id','state','district','website','email','phone','address','category','source_url'];map.innerHTML=`<h3>${e(f.name)} · ${d.rows.length} rows</h3><p>${e(d.note)}<br>Required: name. Only map a genuinely shared identifier—not a file row number. Keep campuses and people distinct.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">${fields.map(field=>`<label>${e(field)}<select style="display:block;width:100%" data-universal-field="${field}"><option value="">Not provided</option>${d.headers.map((h,i)=>`<option value="${i}" ${h.toLowerCase().replaceAll(' ','_')===field||(field==='entity_id'&&/aishe.?code|entity.?id/i.test(h))?'selected':''}>${e(h)}</option>`).join('')}</select></label>`).join('')}</div><label style="display:block;margin:12px 0">Source webpage (optional)<input type="url" id="universal-source" placeholder="https://official-source.example/directory" style="width:100%"></label><label style="display:block;margin:12px 0"><input type="checkbox" id="universal-append" checked> Combine with current results (${raw.length} source records)</label><button class="primary" id="universal-build">Build combined list ↗</button><p>Preview: ${e(JSON.stringify(d.rows[0]||[]))}</p>`;$('#universal-build').onclick=buildUniversal}catch(err){toast(err.message)}}
function buildUniversal(){const mappings=Object.fromEntries($$('[data-universal-field]').filter(el=>el.value!=='').map(el=>[el.dataset.universalField,Number(el.value)]));if(mappings.name===undefined)return toast('Map the name column.');const append=$('#universal-append').checked;if(universalPreview.rows.length+(append?raw.length:0)>5000)return toast('Limit this combined working list to 5,000 records.');const sourceUrl=safeURL($('#universal-source').value),stamp=Date.now(),source=universalFile.name;const records=universalPreview.rows.map((row,i)=>{const mapped=Object.fromEntries(Object.entries(mappings).map(([k,v])=>[k,String(row[v]??'').trim()]));const original=Object.fromEntries(universalPreview.headers.map((h,j)=>[h,row[j]??'']));let entityId=mapped.entity_id||'';if(/^[CURS]-\d+$/.test(entityId))entityId='aishe:'+entityId;return {id:`import:${stamp}:${i}`,name:mapped.name||`Unnamed row ${i+2}`,entityId,state:mapped.state||'',district:mapped.district||'',city:mapped.district||mapped.state||'',website:canonicalWebsite(mapped.website),email:mapped.email||'',phone:mapped.phone||'',address:mapped.address||'',category:mapped.category||'',source,sourceUrl:safeURL(mapped.source_url)||sourceUrl,sourceRow:universalPreview.row_numbers[i],retrieved:new Date().toISOString(),original}});raw=append?[...raw,...records]:records;decisions={};lastMode='upload';lastQuery=`Reconcile ${source}`;plan={city:{name:'Combined'},type:'directory',engine:'Mapped import'};sourceLog=append?sourceLog:[];sourceLog.push({name:source,status:'User-mapped import',detail:'Original fields retained. Mappings supplied by user. No independent verification of contents.'});tab='records';$('#modal').close();$('#table-search').value='';refresh();notice(`Imported ${records.length} records. Use CSV export for the full list; the table shows the first 100 matching rows.`)}
